-- Mage Style 1 Pyromancer replaces Mana Flow (Q 2026-10-17, artifact comment on the Mage Dossier).
-- cards.style_only: 'MG:1' = only in the deck under Pyromancer, '!MG:1' = every Style but Pyromancer.
-- MG-033..039 = the first Pyro set, out of the deck (in_deck false) for a future deck builder.
-- 7 Pyro cards (MG-026..032, Q's set) take the place of the 7 Mage cards with the lowest dmg per game in the sim (Claude pick, Q delegated).
alter table public.cards add column if not exists style_only text;
comment on column public.cards.style_only is '"MG:1" = only in the deck under that Style; "!MG:1" = under every Style but that one; null = always';

update public.champion_styles set name = 'Pyromancer', effect = 'Touch of Flame: every Skill card you paid for that hits clean gives the opponent 1 Ignite (each stack burns 2 HP + 1% Max HP every turn and cuts heals 25%, max 50%; 3 turns, max 4 stacks). Molten Shield: every Block gets Shield 5 this turn; with 1+ Mana, each hit your Block stops gives the attacker 1 Ignite.'
where champion_id = 'MG' and slot = 1;

-- duplicate name: MG-025 keeps Counterspell (facing Skill deals 0), MG-010 (facing card −6) becomes Runic Deflect
update public.cards set name = 'Runic Deflect' where id = 'MG-010';

update public.cards set style_only = '!MG:1' where id in ('MG-001', 'MG-018', 'MG-007', 'MG-008', 'MG-025', 'MG-021', 'MG-016');

on conflict (id) do update set name = excluded.name, type = excluded.type, dmg = excluded.dmg, effect = excluded.effect, effect_json = excluded.effect_json, cost = excluded.cost, style_only = excluded.style_only, in_deck = excluded.in_deck, tags = excluded.tags;
